  Definition rom_cell_check (c : Z * nat * Z) : bool :=
    let '(a, w, v) := c in
    img_check a (a + Z.of_nat w)
    && match rdn ASEGS (fun _ => None) (Z_to_bv 64 a) w with
       | Some bs => bytes_eqb bs (word_to_le_bytes w (Z_to_bv 64 v)) | None => false end.
